import{_ as a,c as n,o as e,a5 as p}from"./chunks/framework.DorIfSpC.js";const g=JSON.parse('{"title":"快了 2.6 倍，然後我發現自己量錯了兩次","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/project/minimax-h3-8step-acceleration"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/project/minimax-h3-8step-acceleration"}],["meta",{"property":"og:title","content":"快了 2.6 倍，然後我發現自己量錯了兩次 | 星智未來"}],["meta",{"name":"twitter:title","content":"快了 2.6 倍，然後我發現自己量錯了兩次 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"快了 2.6 倍，然後我發現自己量錯了兩次\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/project/minimax-h3-8step-acceleration\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/project/minimax-h3-8step-acceleration\\"}}"]]},"headers":[],"relativePath":"project/minimax-h3-8step-acceleration.md","filePath":"project/minimax-h3-8step-acceleration.md","lastUpdated":1788355070000}'),i={name:"project/minimax-h3-8step-acceleration.md"};function t(o,s,l,r,d,c){return e(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="快了-2-6-倍-然後我發現自己量錯了兩次" tabindex="-1">快了 2.6 倍，然後我發現自己量錯了兩次 <a class="header-anchor" href="#快了-2-6-倍-然後我發現自己量錯了兩次" aria-label="Permalink to &quot;快了 2.6 倍，然後我發現自己量錯了兩次&quot;">​</a></h1><blockquote><p>MiniMax H3 的 8 步加速實測、兩個文件上查不到的坑，和一個我公開收回的畫質結論</p></blockquote><p><strong>作者</strong>：Ray <strong>日期</strong>：2026 年 9 月 2 日</p><hr><p>8 月底，MiniMax H3 多了一個官方的加速方案：alibaba-pai 放出 <strong>PDD 蒸餾 LoRA</strong>，而且有 Ref2VA 專屬檔——20 步變 8 步。</p><p>我在 <a href="https://runpod.io?ref=s3bs0r0v" target="_blank" rel="noreferrer">RunPod</a> 上自架 H3 拍一部連載短劇，一集 22 顆鏡頭，全部 20 步跑要四個多小時。如果這東西是真的，那是一個晚上跟兩個晚上的差別。</p><p>我花了一個晚上把它接起來、量了兩組對照。</p><p><strong>結論是值得接。但那個晚上真正花掉時間的不是接線，是搞清楚我量到的數字算不算數。</strong></p><hr><h2 id="先講結果" tabindex="-1">先講結果 <a class="header-anchor" href="#先講結果" aria-label="Permalink to &quot;先講結果&quot;">​</a></h2><p>同一個鏡頭、同一顆種子、同一組參考圖，只換取樣路徑：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>192 影格（8.0 秒），768 × 1376，Ref2VA</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  20 步  res_multistep       683.87 秒     3.56 秒／影格</span></span>
<span class="line"><span>   8 步  euler ＋ PDD Acc     262.09 秒     1.37 秒／影格</span></span>
<span class="line"><span>  ─────────────────────────────────────────</span></span>
<span class="line"><span>                             快 2.6 倍</span></span></code></pre></div><p>一集 22 顆鏡頭：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>全 20 步   ≈ 4.2 小時</span></span>
<span class="line"><span>全  8 步   ≈ 1.6 小時</span></span></code></pre></div><p>這個比值跟你租哪張卡無關——它是同一台機器上的比值。</p><hr><h2 id="接線-不是「加一個-lora」-是換一條取樣路徑" tabindex="-1">接線：不是「加一個 LoRA」，是換一條取樣路徑 <a class="header-anchor" href="#接線-不是「加一個-lora」-是換一條取樣路徑" aria-label="Permalink to &quot;接線：不是「加一個 LoRA」，是換一條取樣路徑&quot;">​</a></h2><p>這是我一開始理解錯的地方。我以為就是掛個 LoRA 節點，實際上<strong>取樣器和 sigma 的來源都要換掉</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原本</span></span>
<span class="line"><span>  載入擴散模型 ──────────────────────► 基礎引導器</span></span>
<span class="line"><span>  BasicScheduler（simple / 20 步）───► SamplerCustomAdvanced 的 Sigma 值</span></span>
<span class="line"><span>  K採樣器選擇 = res_multistep</span></span>
<span class="line"><span></span></span>
<span class="line"><span>改成</span></span>
<span class="line"><span>  載入擴散模型 ─► ModelSamplingMiniMaxH3 ─► MiniMax H3 PDD Acc LoRA (Apply)</span></span>
<span class="line"><span>                        (12.0 / 3.0)              │</span></span>
<span class="line"><span>                                    ┌── model ────┤</span></span>
<span class="line"><span>                                    ▼             └── sigmas ──┐</span></span>
<span class="line"><span>                             基礎引導器                         ▼</span></span>
<span class="line"><span>                                                 SamplerCustomAdvanced 的 Sigma 值</span></span>
<span class="line"><span>  K採樣器選擇 = euler</span></span>
<span class="line"><span>  ⛔ BasicScheduler 整個旁路掉</span></span></code></pre></div><p>⭐ <strong>sigmas 要接 Apply 節點的輸出，不是 BasicScheduler。</strong> 那組 sigma 是訓練時的區塊邊界，不是一般的排程曲線。<code>12.0 / 3.0</code> 那兩個數字也要照抄，官方文件寫的是 &quot;exactly&quot;。</p><p>節點包裡附了 <code>example_workflows/</code>，我本來想直接載——<strong>但它們在新版 ComfyUI 打不開</strong>。JSON 裡寫的是舊節點名 <code>MiniMaxH3SigmaShift</code>，現在改叫 <code>ModelSamplingMiniMaxH3</code>。自己接反而比較快。</p><p>⭐ 順帶一個讓人安心的設計：這個節點包有 <code>on_off_grid = error</code>。**接錯會直接報錯，不會默默產出垃圾。**所以可以放心接，錯了它會講。</p><hr><h2 id="坑一-節點裝好了-搜不到" tabindex="-1">坑一：節點裝好了，搜不到 <a class="header-anchor" href="#坑一-節點裝好了-搜不到" aria-label="Permalink to &quot;坑一：節點裝好了，搜不到&quot;">​</a></h2><p><code>git clone</code> 到 <code>custom_nodes/</code> 之後，搜尋框打節點名稱，<strong>「沒有結果」</strong>。</p><p>三個原因疊在一起，每一個單獨看都很蠢，但疊起來會讓你懷疑是不是裝壞了：</p><p><strong>一、ComfyUI 只在啟動時掃描 <code>custom_nodes/</code>。</strong> clone 完不會自己載入，要重啟。</p><p><strong>二、要用「顯示名稱」搜，不是 class 名稱。</strong> 打完整的 <code>MiniMaxH3PDDAccApply</code> 找不到，打 <code>pdd</code> 才會跳出來——因為節點包定義了 <code>NODE_DISPLAY_NAME_MAPPINGS</code>，搜尋比對的是顯示名。</p><p><strong>三、另一個必要的節點根本不在這個包裡。</strong> <code>ModelSamplingMiniMaxH3</code> 是 ComfyUI 內建的，標籤是 <code>Comfy</code>。所以搜 <code>pdd</code> 永遠找不到它，要搜 <code>shift</code>。</p><p>我在第三點上卡了一陣子，因為官方範例的 JSON 用的是舊名，而我照著那個名字去搜。</p><hr><h2 id="坑二-pdd-file-下拉是空的——而檔案明明就在" tabindex="-1">坑二：<code>pdd_file</code> 下拉是空的——而檔案明明就在 <a class="header-anchor" href="#坑二-pdd-file-下拉是空的——而檔案明明就在" aria-label="Permalink to &quot;坑二：\`pdd_file\` 下拉是空的——而檔案明明就在&quot;">​</a></h2><p>這個花最久，而且<strong>症狀完全誤導人</strong>。</p><p>節點出現了，LoRA 下載完了，<code>ls</code> 看得到 1.66 GB 躺在 <code>/workspace/ComfyUI/models/pdd_acc/</code>。但下拉選單是空的，欄位顯示 <code>undefined</code>。重啟沒用，硬重新整理沒用。</p><p>我花了一段時間在快取和權限上繞。然後停下來，<strong>直接問 server</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8188/object_info/MiniMaxH3PDDAccApply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import sys,json; d=json.load(sys.stdin); </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">print(d[&#39;MiniMaxH3PDDAccApply&#39;][&#39;input&#39;][&#39;required&#39;][&#39;pdd_file&#39;][0])&quot;</span></span></code></pre></div><p>回傳 <code>[]</code>。<strong>不是前端沒更新，是 server 真的看不到那個檔案。</strong></p><p>那就換一個問題：它到底在哪裡找？</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aux</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[m]ain.py&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># /opt/venv/bin/python3 /ComfyUI/main.py ... --extra-model-paths-config /ComfyUI/extra_model_paths.yaml</span></span></code></pre></div><p><strong>ComfyUI 根本不是跑在 <code>/workspace/ComfyUI</code>，是跑在 <code>/ComfyUI</code>。</strong></p><p>RunPod 這類範本的設計是：程式放在容器的 <code>/ComfyUI</code>，模型放在持久磁碟 <code>/workspace/ComfyUI/models</code>，靠 <code>extra_model_paths.yaml</code> 掛過去。標準的資料夾（checkpoints、loras、vae、diffusion_models）全都沒問題——<strong>所以你不會懷疑到這裡。</strong></p><p>但這個節點包新增了一種資料夾類型，而它是這樣寫的：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">_pdd_dir </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os.path.join(folder_paths.models_dir, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pdd_acc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># = /ComfyUI/models/pdd_acc</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">folder_paths.add_model_folder_path(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pdd_acc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, _pdd_dir, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">is_default</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>**它繞過了 yaml，直接用 <code>models_dir</code>。**所以它去 <code>/ComfyUI/models/pdd_acc</code> 找，而那裡是空的。</p><p>修法是一行 symlink：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /ComfyUI/models/pdd_acc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /workspace/ComfyUI/models/pdd_acc/minimax_h3_ref2va_pdd_acc_8step_comfyui.safetensors</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       /ComfyUI/models/pdd_acc/</span></span></code></pre></div><p>⚠️ <code>/ComfyUI</code> 在容器的暫存檔案系統上，<strong>關機就沒了——這行每次開機都要重做。</strong></p><p>⭐ 可以推廣的一條：**任何「自訂節點自己新增一種模型資料夾」的套件，在這類範本上都會踩到同一個坑。**症狀一律是「節點有出現、下拉是空的」，而那個症狀會讓你往快取和重啟的方向找很久。</p><p><strong>下次遇到，第一件事是 <code>ps aux | grep main.py</code>，看它到底跑在哪。</strong></p><hr><h2 id="然後是真正麻煩的部分-我量錯了兩次" tabindex="-1">然後是真正麻煩的部分：我量錯了兩次 <a class="header-anchor" href="#然後是真正麻煩的部分-我量錯了兩次" aria-label="Permalink to &quot;然後是真正麻煩的部分：我量錯了兩次&quot;">​</a></h2><p>接起來只花了那晚的前三分之一。剩下的時間全部花在「這個數字算不算數」。</p><h3 id="錯誤一-第一次跑的數字不能用" tabindex="-1">錯誤一：第一次跑的數字不能用 <a class="header-anchor" href="#錯誤一-第一次跑的數字不能用" aria-label="Permalink to &quot;錯誤一：第一次跑的數字不能用&quot;">​</a></h3><p>第一次量，20 步是 <strong>682.63 秒</strong>。我記成基準，算出加速比 2.57 倍，還挺得意。</p><p>然後我又跑了一次一模一樣的設定：<strong>510.74 秒。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>20 步  第一次   682.63s   ← 含模型首次載入</span></span>
<span class="line"><span>20 步  第二次   510.74s   ← 穩態</span></span>
<span class="line"><span>差               171.89s   ≈ 第一次的 25%</span></span></code></pre></div><p>這個錯有一個很討厭的性質：<strong>它是系統性偏誤，不是隨機誤差。</strong></p><p>你一定是先跑基準版、再接線、再跑加速版。所以<strong>被首次載入拖累的永遠是基準版</strong>，加速看起來永遠比實際好。如果沒發現，我會對外宣稱一個高估的數字。</p><p>而且我第一次量加速版時犯了同一個錯——那次含了 PDD LoRA 的首次載入，所以偏高。上面那組 192 影格的數字，是兩邊都跑到第二次之後才記的。</p><blockquote><p><strong>要比對任何設定，兩邊都跑到穩態再記數字。</strong></p></blockquote><h3 id="錯誤二-我下了一個站不住的畫質結論" tabindex="-1">錯誤二：我下了一個站不住的畫質結論 <a class="header-anchor" href="#錯誤二-我下了一個站不住的畫質結論" aria-label="Permalink to &quot;錯誤二：我下了一個站不住的畫質結論&quot;">​</a></h3><p>速度確定之後，我開始比畫質。抽同樣六個時間點的臉部特寫，兩版並排，寫下：</p><blockquote><p>8 步的皮膚明顯更平滑、蠟感重，毛孔與細紋少很多；眉毛變得又黑又硬，像畫上去的。</p></blockquote><p><strong>那個結論我收回了。</strong></p><p>因為 8 步版的<strong>走位變了</strong>：同一顆種子，換一條取樣路徑，人物的位置和景別就不一樣，8 步那版的臉在畫面裡大得多。為了並排比較，我把 20 步的小臉放大、8 步的大臉縮小——</p><p><strong>那個縮放本身就會製造「一個糊、一個平滑」的假象。</strong></p><p>我拿著一組被自己的前處理污染的圖，寫了一段看起來很專業的觀察。直到我把兩支<strong>原始影片</strong>並排給人看，得到的回答是：</p><blockquote><p>其實我看不大出來差別。</p></blockquote><p><strong>在沒有乾淨對照的情況下，直接看原片的判斷比我的裁切比對可信。</strong></p><p>要真的測畫質，得拿到景別相同的兩版。但同種子在不同取樣路徑下走位就是會變——<strong>所以這個對照可能根本做不出來。</strong></p><p>與其追一個做不出來的對照，不如直接用，出問題再說。</p><hr><h2 id="唯一可以確定的代價-走位會變" tabindex="-1">唯一可以確定的代價：走位會變 <a class="header-anchor" href="#唯一可以確定的代價-走位會變" aria-label="Permalink to &quot;唯一可以確定的代價：走位會變&quot;">​</a></h2><p>這一項量兩次都一樣，而且它比畫質重要：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同種子、同參考圖、同提示詞，只換取樣路徑</span></span>
<span class="line"><span>  →  構圖、景別、人物走位【都會不一樣】</span></span></code></pre></div><p>第一支測試裡加速版景別變寬、人變小；第二支裡角色多做了一個拱手的動作、鏡頭更近。</p><p>實務上的意思是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>⛔ 不能把 8 步版當成 20 步版「同一顆的另一版」來剪</span></span>
<span class="line"><span>⭐ 決定用幾步之後就固定，不要中途換</span></span></code></pre></div><p>如果你已經拍了半集 20 步，中途換成 8 步，那半集的構圖邏輯會斷掉。</p><hr><h2 id="我原本最擔心的事沒有發生" tabindex="-1">我原本最擔心的事沒有發生 <a class="header-anchor" href="#我原本最擔心的事沒有發生" aria-label="Permalink to &quot;我原本最擔心的事沒有發生&quot;">​</a></h2><p>在跑之前，我最怕的不是畫質，是<strong>表演</strong>。</p><p>我之前實測過一次：同一份精確到 0.1 秒、有九個節拍的表情腳本，跑 226 影格全中，跑 362 影格<strong>全部跳過</strong>——臉從平靜直接跳到大笑，中間的微表情一格都沒有。</p><p>蒸餾把 20 步砍成 8 步，看起來就是同一類的風險：<strong>細微的臉部運動會不會被一起磨掉？</strong></p><p>所以我特別設計了一顆測試鏡頭，要的是「真心的笑」——眼睛先笑（下眼瞼上推、眼尾細紋），嘴角<strong>半秒之後</strong>才跟上。那個順序寫錯就變成社交假笑，是這類戲最挑剔的動作。</p><p>兩版跑出來：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✅ 笑容有出現     兩版同一個時間點都是閉唇的溫和微笑</span></span>
<span class="line"><span>✅ 眼睛有瞇起     兩版後段都看得到下眼瞼上推</span></span>
<span class="line"><span>✅ 臉不是死的     跟 362 影格那次完全不同</span></span></code></pre></div><p><strong>8 步做得到表情。</strong></p><p>⚪ 至於「眼睛先、嘴角後」那個順序有沒有精確執行——我測了兩版都沒有乾淨成立，但那是<strong>我的分鏡設計問題</strong>（鞠躬的動作把轉變遮住了），不是步數的問題。那是另一篇的事。</p><hr><h2 id="所以" tabindex="-1">所以 <a class="header-anchor" href="#所以" aria-label="Permalink to &quot;所以&quot;">​</a></h2><p><strong>接起來的成本</strong>：一個晚上，其中三分之二花在確認數字。文件上查不到的坑有兩個，這篇都寫了。</p><p><strong>買到的東西</strong>：一集從 4.2 小時變 1.6 小時。</p><p><strong>我的用法</strong>：預設全部 8 步。**看不出差別，就不要為它付四倍的時間。**真的有哪一顆出來覺得糊，那一顆單獨用 20 步重跑就好——每顆是獨立生成，沒有綁定成本。</p><p><strong>如果只能帶走一句</strong>：不是「8 步很好用」，是</p><blockquote><p>你量到的第一個數字，通常包含一個你沒注意到的東西。</p></blockquote><p>我這次是首次載入。上一次是我把別的工作排進同一張卡。再上一次是我用被自己縮放污染的圖去比畫質。</p><p><strong>自架真正買到的，是這些錯誤會當場現形。</strong> 在 API 那一端，你只會拿到一個數字，而且沒有機會知道它是怎麼來的。</p><hr><p><em>本文的測試環境：<a href="https://runpod.io?ref=s3bs0r0v" target="_blank" rel="noreferrer">RunPod</a> 租用之 GPU，MiniMax H3 剪枝 INT8 開源權重，於 ComfyUI 部署，Ref2VA 模式，輸出 768 × 1376。 加速使用 alibaba-pai 官方 PDD 蒸餾 LoRA（<code>MiniMax-H3-Ref2VA-Acc-8Step</code>）， 搭配 <a href="https://github.com/Jalen-Brunson/ComfyUI-MiniMax-H3-PDD-Acc" target="_blank" rel="noreferrer">ComfyUI-MiniMax-H3-PDD-Acc</a> 節點包， euler ／ sigma shift 12.0 ／ 3.0 ／ nfe 8 ／ CFG 1.0。計時為 2026-09-02。</em></p><p><em>成本的完整比較見<a href="./ai-video-cost-selfhost">〈那張 AI 影片比價表，少了一列〉</a>。</em></p><p><em>本文的 RunPod 連結為推薦連結，透過它註冊我會獲得少量回饋，不影響你的價格。</em></p><p><em><a href="https://aidream.com.tw" target="_blank" rel="noreferrer">aidream.com.tw</a></em></p>`,103)])])}const k=a(i,[["render",t]]);export{g as __pageData,k as default};
